# old slug -> (new slug, new title). Section pages drive the GeLearn nav
# (useNavConfig reads title + slug); HomePage teaser cards link by slug.
RENAMES = {
    "technology":   ("geacademy",        "GeAcademy"),
    "case-studies": ("research",         "Research"),
    "tenders":      ("policies-tenders", "Policies & Tenders"),
}
REVERSE = {
    "geacademy":        ("technology",   "Technology Deep Dives"),
    "research":         ("case-studies", "Case Studies"),
    "policies-tenders": ("tenders",      "Tenders & Opportunities"),
}


def _rename_section_pages(apps, mapping):
    GeLearnSectionPage = apps.get_model("pages", "GeLearnSectionPage")
    Page = apps.get_model("wagtailcore", "Page")
    Revision = apps.get_model("wagtailcore", "Revision")

    for old_slug, (new_slug, new_title) in mapping.items():
        for page in GeLearnSectionPage.objects.filter(slug=old_slug):
            old_url_path = page.url_path
            new_url_path = old_url_path[: -len(old_slug) - 1] + new_slug + "/"
            page.slug = new_slug
            page.section_type = new_slug
            page.title = new_title
            page.draft_title = new_title
            page.url_path = new_url_path
            page.save()
            # Descendants (none today) keep their paths consistent.
            for child in Page.objects.filter(url_path__startswith=old_url_path).exclude(pk=page.pk):
                child.url_path = new_url_path + child.url_path[len(old_url_path):]
                child.save(update_fields=["url_path"])
            # Keep the latest revision in sync so a later publish doesn't revert the rename.
            if page.latest_revision_id:
                rev = Revision.objects.get(pk=page.latest_revision_id)
                content = dict(rev.content)
                content.update(
                    slug=new_slug, section_type=new_slug, url_path=new_url_path,
                    title=new_title, draft_title=new_title,
                )
                rev.content = content
                rev.save(update_fields=["content"])


def _rename_teaser_blocks(stream, mapping):
    changed = False
    for block in stream:
        value = block.get("value") or {}
        if block.get("type") == "card" and value.get("slug") in mapping:
            value["slug"], value["label"] = mapping[value["slug"]]
            changed = True
    return changed


def _rename_home_teaser(apps, mapping):
    HomePage = apps.get_model("pages", "HomePage")
    Revision = apps.get_model("wagtailcore", "Revision")
    for home in HomePage.objects.all():
        raw = [dict(b, value=dict(b.get("value") or {})) for b in home.gelearn_teaser.raw_data]
        if _rename_teaser_blocks(raw, mapping):
            home.gelearn_teaser = raw
            home.save(update_fields=["gelearn_teaser"])
        if home.latest_revision_id:
            rev = Revision.objects.get(pk=home.latest_revision_id)
            content = dict(rev.content)
            teaser = content.get("gelearn_teaser")
            if isinstance(teaser, str):
                blocks = json.loads(teaser)
                if _rename_teaser_blocks(blocks, mapping):
                    content["gelearn_teaser"] = json.dumps(blocks)
                    rev.content = content
                    rev.save(update_fields=["content"])


def forwards(apps, schema_editor):
    _rename_section_pages(apps, RENAMES)
    _rename_home_teaser(apps, RENAMES)


def backwards(apps, schema_editor):
    _rename_section_pages(apps, REVERSE)
    _rename_home_teaser(apps, REVERSE)


